// Original ECHOES educational narration. Grounded in NASA records, not historical quotations.
const entries=[];
const item=(metadata,chapters)=>entries.push({...metadata,chapters});
item({id:'surveyor1',name:'Surveyor 1',world:'Moon',place:'Oceanus Procellarum',lat:-2.46,lon:-43.32,years:'1966 – 1967',subtitle:'A gentle landing before the first footsteps.',theme:'Learning to land',url:'https://science.nasa.gov/mission/surveyor-1/',imageUrl:'https://assets.science.nasa.gov/dynamicimage/assets/science/psd/solar/2023/07/surveyor.jpg?w=1100',caption:'NASA · Surveyor spacecraft design reference from the mission archive; not a photograph of Surveyor 1 on the Moon.',end:'Surveyor 1 landed June 2, 1966. Its primary mission ended July 14, 1966; contact continued until January 7, 1967. The lander stayed on the Moon.',stats:[['1966','Lunar landing'],['11,240','Images by July 6'],['1967','Final contact']],parts:[['Television camera','The camera returned panoramic and close views that helped engineers examine lunar terrain and the area around the landing feet.'],['Landing feet','Three legs and shock-absorbing footpads supported a controlled soft landing and provided measurements of the landing forces.'],['Solar panel','The panel collected sunlight for the lander’s electrical system. Surveyor was a stationary spacecraft, not a wheeled rover.']],question:'Why did Surveyor 1 matter before Apollo?',choices:['It demonstrated controlled landing and surface operations.','It carried astronauts home.','It proved that all lunar soil was liquid.'],correct:0,why:'A successful robotic landing and transmitted pictures helped establish that spacecraft could land and operate on the lunar surface.'},[
['A robot arrives before the boots','OCEAN OF STORMS · JUNE 1966','Before astronauts could trust a landing on the Moon, engineers needed practice with a real surface. Surveyor 1 arrived in Oceanus Procellarum, the Ocean of Storms, on June 2, 1966. It slowed itself with rocket propulsion and settled onto three legs with wide supporting footpads. No person was inside. This was a remotely operated spacecraft making a careful engineering test. A successful arrival would show that landing equipment, instruments and communications could work together far from Earth, helping prepare the way for Apollo.'],
['Three feet become measuring tools','THE LANDING STRUCTURE','The feet were more than supports for a camera. Surveyor’s landing structure included shock absorbers and strain gauges that helped describe the forces of touchdown. Engineers could connect those measurements with the pictures sent home. The camera showed the ground, nearby rocks and the marks made by the lander itself. Instead of assuming that every part of the Moon behaved the same way, the team examined evidence from one actual place. A small stationary robot had turned an unfamiliar surface into something measurable.'],
['Pictures answer practical questions','A CAMERA ON THE GROUND','Surveyor 1’s television camera gave the team views from the surface rather than from a passing spacecraft. By July 6, 1966, it had transmitted 11,240 high-resolution images during two communications sessions. Those pictures revealed details of the surrounding terrain and helped engineers assess the landing. The mission was not a geological survey of the entire Moon. Its importance came from combining a successful controlled landing with observations taken at the landing site, demonstrating a practical way to operate and investigate there.'],
['A quiet beginning to a larger journey','FINAL CONTACT · JANUARY 1967','The primary mission was complete by July 14, 1966, but controllers maintained contact until January 7, 1967. Surveyor 1 then became hardware left on the Moon. Its work had already travelled home as images and engineering measurements. The original spacecraft did not need to return for those observations to remain useful. When we explore its design today, we are looking at an illustration of its working years. The historic landing and the lander’s present appearance are different questions, and the records establish the former.']]);

item({id:'surveyor5',name:'Surveyor 5',world:'Moon',place:'Mare Tranquillitatis',lat:1.42,lon:23.20,years:'1967',subtitle:'A small analyzer reads the soil.',theme:'Chemistry without a scoop',url:'https://science.nasa.gov/mission/surveyor-5/',imageUrl:'https://assets.science.nasa.gov/dynamicimage/assets/science/psd/solar/2023/07/surveyor-3.jpg?w=1100',caption:'NASA · Surveyor spacecraft design reference from the Surveyor 5 mission page; not a surface photograph of the retired lander.',end:'Surveyor 5 landed September 11, 1967. Contact was lost December 16, 1967, after a mission that returned images and lunar soil chemistry measurements.',stats:[['1967','Mare Tranquillitatis'],['20,018','Pictures transmitted'],['Alpha','Soil analysis']],parts:[['Television camera','The camera photographed the landing area and the spacecraft’s surroundings. Surveyor 5 returned 20,018 pictures.'],['Alpha-scattering analyzer','This instrument measured the relative abundance of chemical elements in lunar material. It replaced the surface sampler carried by an earlier Surveyor; Surveyor 5 had no digging scoop.'],['Solar panel','Sunlight supported the electrical system used for communications, imaging and instrument operations during the mission.']],question:'How did Surveyor 5 investigate lunar soil?',choices:['It sent astronauts with a bucket.','It used an alpha-scattering instrument, not a digging scoop.','It flew rocks back to Earth.'],correct:1,why:'Surveyor 5 used an alpha-scattering instrument to investigate elemental composition. It did not carry the earlier Surveyor surface sampler.'},[
['A leak nearly ends the journey','MARE TRANQUILLITATIS · SEPTEMBER 1967','Surveyor 5 almost lost its chance to explore. A helium leak affected its propulsion system during the journey, and engineers had to find a way to complete the descent. The lander reached Mare Tranquillitatis on September 11, 1967, settling on a slope inside a small crater. Reaching the ground was only the beginning of the question it carried. This Surveyor would add chemical measurements to the pictures and engineering observations that earlier robotic visitors had used to study the lunar surface.'],
['Read the material without digging','AN ALPHA-SCATTERING INSTRUMENT','Surveyor 5’s scientific tool was different from the scoop on an earlier Surveyor. An alpha-scattering instrument investigated the relative abundance of chemical elements in material at the surface. Its measurements helped scientists ask what the soil was made of. A small magnet on a landing foot also examined magnetic properties. These instruments had specific jobs; their results should not be confused with collecting rocks for return to Earth. Surveyor 5 performed its chemical investigation where it stood and transmitted the observations through its radio link.'],
['An ordinary-looking surface holds chemistry','FROM PICTURES TO COMPOSITION','The camera and chemical instrument offered different kinds of evidence. Photographs described the surroundings, while the analyzer investigated composition. Together they supported the interpretation that the material at this mare site was basaltic, connecting it with volcanic rock. Surveyor 5 ultimately transmitted 20,018 pictures during its working periods. That was a much richer record than a single postcard of the landing. Scientists could compare observations and ask how the local surface fitted into the wider geological story of the Moon.'],
['The analyzer becomes an artifact','CONTACT LOST · DECEMBER 1967','Contact with Surveyor 5 was lost on December 16, 1967. The spacecraft stayed in Mare Tranquillitatis, and its records remained available on Earth. Its story is useful partly because it shows how two similar-looking machines can carry different experiments. A model with an imaginary scoop would teach the wrong lesson about this mission. The illustration here identifies its camera, chemical analyzer and solar panel. These represent its working design, while the precise present condition of the abandoned hardware is not supplied by this historical mission record.']]);

item({id:'surveyor6',name:'Surveyor 6',world:'Moon',place:'Sinus Medii',lat:.473,lon:-1.427,years:'1967',subtitle:'The lander that took a tiny second step.',theme:'A hop changes the view',url:'https://science.nasa.gov/mission/surveyor-6/',imageUrl:'https://assets.science.nasa.gov/dynamicimage/assets/science/psd/solar/2023/07/surveyor-4.jpg?w=1100',caption:'NASA · Surveyor spacecraft design reference from the Surveyor 6 mission page; this illustrates the design rather than its current condition.',end:'Surveyor 6 landed November 10, 1967, hopped on November 17, and entered hibernation later that month. Contact was briefly recovered December 14, 1967.',stats:[['2.5 m','Approximate sideways hop'],['29,952','Images returned'],['1967','Lunar mission']],parts:[['Television camera','The camera photographed the surface before and after the hop, allowing a new view of the original landing marks.'],['Landing feet and thrusters','The lander briefly fired its thrusters, lifted about three meters and touched down about 2.5 meters west of its original point. It stayed on the Moon.'],['Solar panel','The panel collected sunlight for the stationary lander’s electrical system; the mission did not use rover wheels.']],question:'What did Surveyor 6’s hop allow its camera to examine?',choices:['Earth from a new orbit.','Its original landing marks from a changed viewpoint.','An astronaut standing at the site.'],correct:1,why:'The short hop moved the camera’s viewpoint and exposed the first landing position for observation; Surveyor 6 did not leave the Moon.'},[
['Set down in the Central Bay','SINUS MEDII · NOVEMBER 1967','Surveyor 6 landed in Sinus Medii, the Central Bay, on November 10, 1967. Its mission continued the robotic investigation of terrain that could help prepare for human exploration. The spacecraft carried a television camera, an alpha-scattering instrument and magnets on its landing feet. Each instrument offered a different observation: the appearance of the site, the composition of surface material, or its magnetic properties. But this lander also had a chance to do something unusual after its first successful touchdown: change where it stood.'],
['Three meters up, then down again','A SHORT HOP · NOVEMBER 17','On November 17, controllers briefly fired Surveyor 6’s three liquid-propellant thrusters. The spacecraft rose about three meters and landed roughly 2.5 meters west of its original point. This was a short hop on the Moon, not a journey back to Earth and not a drive on wheels. Its landing feet became supports a second time. The change in position was small compared with the size of the Moon, but large enough to give the camera a new view of the nearby ground.'],
['Look back at the place you stood','THE FIRST FOOTPRINTS COME INTO VIEW','From its new position, Surveyor 6 could photograph the marks made during its first landing. Scientists and engineers could examine how the surface had responded to the feet and rocket exhaust. The shifted camera position also supported stereo imaging: two viewpoints can help reveal the shape of a scene. During its mission the lander returned 29,952 images and gathered chemical measurements. A little movement had made the same patch of ground useful in a different way, linking landing engineering with close observation.'],
['A short journey with a long record','THE APPROACH OF LUNAR NIGHT','The approach of lunar night ended Surveyor 6’s main working period in November 1967. Controllers placed it in hibernation, and briefly regained contact on December 14. Its journey remained a lunar one: the robot never returned to Earth. The archived pictures and chemical data preserve what it observed during its mission. In this experience, a design illustration helps explain the hop and the hardware that made it possible. It is not a measured reconstruction of the spacecraft’s exact appearance after decades on the surface.']]);

item({id:'surveyor7',name:'Surveyor 7',world:'Moon',place:'Highlands north of Tycho',lat:-40.97,lon:-11.44,years:'1968',subtitle:'A robot reaches rougher ground.',theme:'Comparing lunar landscapes',url:'https://science.nasa.gov/mission/surveyor-7/',imageUrl:'https://assets.science.nasa.gov/dynamicimage/assets/science/psd/solar/2023/07/surveyor-5.jpg?w=1100',caption:'NASA · Surveyor spacecraft design reference from the Surveyor 7 mission page; not a photograph of the actual retired lander.',end:'Surveyor 7 landed January 10, 1968, north of Tycho crater. Its final working period ended February 21, 1968.',stats:[['1968','Highland landing'],['3','Analyzed sample settings'],['Tycho','Nearby crater']],parts:[['Television camera','The camera documented the highland landing area and the work of the sampling equipment.'],['Sampler and alpha analyzer','The sampler arm helped free a stuck alpha-scattering instrument and moved it among undisturbed surface, a rock, and disturbed soil for chemical measurements.'],['Solar panel','The panel collected sunlight for the lander’s powered instruments and communications during its working mission.']],question:'Why was Surveyor 7’s landing site scientifically useful?',choices:['It sampled a highland setting that could be compared with earlier mare sites.','It was a lake filled with liquid water.','It was the same location as every earlier Surveyor.'],correct:0,why:'Surveyor 7 landed in the highlands near Tycho, giving scientists a different geological setting from earlier mare landings.'},[
['The last Surveyor seeks different ground','NEAR TYCHO · JANUARY 1968','The earlier successful Surveyors had helped answer practical questions about landing and operating on the Moon. For Surveyor 7, NASA chose a site with a different scientific opportunity. It landed on January 10, 1968, on material thrown out around Tycho crater in the lunar highlands. This was rougher country than the mare locations visited earlier. By comparing observations from different settings, scientists could investigate differences in lunar material instead of treating one landing site as a description of the entire Moon.'],
['A helping arm frees an experiment','AN INSTRUMENT NEEDS A NUDGE','After landing, the alpha-scattering instrument did not reach its intended position on the ground. Controllers used the surface sampler to help move it down. The sampler then helped place the analyzer at different targets, including undisturbed surface material, a rock and soil disturbed by the scoop. This is an example of two tools working together: the arm changed what could be reached, while the chemical instrument measured the material. A robot’s useful work came from the relationship between its parts, not one instrument acting alone.'],
['Ask how one landscape differs from another','THE HIGHLANDS ENTER THE RECORD','The camera photographed the surroundings while the sampler dug, pressed and moved material and equipment. Chemical measurements at several targets let scientists compare what the instrument encountered. The broader question was how a highland site differed from the mare sites investigated by other Surveyors. Careful comparisons required knowing where a measurement came from and how it was obtained. A photograph supplied context, but the chemical readings supplied another kind of evidence. Both were needed to build a stronger account of the material on the ground.'],
['One program ends, another approaches','MISSION END · FEBRUARY 1968','Surveyor 7’s second lunar-day operations continued into February, ending on February 21, 1968. It was the final mission of the original Surveyor series. The successful landers had shown that remotely controlled machines could survive touchdown, observe the surface and run useful experiments. Their measurements helped prepare for Apollo while contributing scientific findings of their own. Surveyor 7 remained near Tycho after communications ended. The historical spacecraft illustration shown here explains its instruments; it does not establish the exact present condition of the equipment left behind.']]);

item({id:'falcon',name:'Falcon descent stage',world:'Moon',place:'Hadley-Apennine · Apollo 15',lat:26.08,lon:3.66,years:'1971',subtitle:'A home base becomes a landmark.',theme:'A longer lunar expedition',url:'https://www.nasa.gov/mission/apollo-15/',imageUrl:'https://www.nasa.gov/wp-content/uploads/2021/07/apollo_15_moon_landing_28_eva3_scott_w_us_flag_as15-88-11863hr.jpg?w=1400',caption:'NASA · AS15-88-11863: an Apollo 15 astronaut salutes beside the flag, with Falcon in the background, 1971; both stages were still present during this photograph.',end:'Apollo 15’s Falcon landed July 30, 1971. Its ascent stage departed August 2 with David Scott and James Irwin. Only the descent stage remained at the landing site.',stats:[['1971','Apollo 15'],['2','Stages, different journeys'],['Hadley','Lunar landing region']],parts:[['Gold descent-stage body','The lower stage carried landing equipment and supported the upper ascent stage. It remained at Hadley-Apennine when the crew left.'],['Landing legs','Four legs and wide footpads supported Falcon at its lunar landing site.'],['Descent-engine bell','The descent engine slowed Falcon toward the surface during landing. A separate engine on the ascent stage later carried the astronauts away.']],question:'Which part of Falcon remained at Hadley-Apennine?',choices:['The complete lander with its crew cabin.','The lower descent stage.','Only the departing ascent engine.'],correct:1,why:'The ascent stage carried the crew away; the descent stage and its landing structure stayed at the Apollo 15 site.'},[
['A base beside mountains and a rille','HADLEY-APENNINE · JULY 1971','Apollo 15 brought a longer style of human surface exploration to the Moon in 1971. David Scott and James Irwin descended in the Lunar Module Falcon while Alfred Worden remained in lunar orbit. Their destination was Hadley-Apennine, a region of mountains and a winding feature called Hadley Rille. Falcon was the crew’s landing vehicle and their base during surface work. It also carried equipment for the expedition. Its lower descent stage would become a permanent part of the landing site after the astronauts departed.'],
['The stage underneath the story','A LANDING SYSTEM WITH FOUR FEET','Falcon’s descent stage included the landing engine, lower structure and four landing legs. The wide footpads supported the spacecraft on the lunar ground. Above this lower stage sat the ascent stage, containing the cabin that the crew would need for departure. The two stages belonged to one working spacecraft but had different jobs. The illustration here shows the lower stage that stayed behind. A photograph taken during the visit can show the complete Lunar Module; it must not be mistaken for the configuration left at the site.'],
['A home base extends the science','APOLLO 15 SURFACE EXPLORATION','From Falcon, Scott and Irwin carried out a program of surface excursions, geological observations, sample collection and experiment deployment. Apollo 15 was the first mission to use the Lunar Roving Vehicle, helping astronauts travel farther than walking alone allowed. Falcon and the rover were separate pieces of equipment with connected roles in the expedition. The landing vehicle made the stay possible; the rover extended its reach. Their story explains how transport, shelter and scientific tools can work together to support an investigation of another world.'],
['One stage leaves; one stays','ASCENT · AUGUST 2, 1971','On August 2, Falcon’s ascent stage lifted Scott and Irwin away from the surface toward their rendezvous in lunar orbit. The lower descent stage remained at Hadley-Apennine, along with other equipment left by the expedition. Departure changed the meaning of the structure beneath the cabin: a landing system had become a historical landmark. Its scientific value is connected to the observations and samples the expedition enabled. Our model is a teaching illustration, while mission photographs and later records provide dated evidence about the actual place and hardware.']]);

item({id:'viking2',name:'Viking 2',world:'Mars',place:'Utopia Planitia',lat:47.64,lon:134.29,years:'1976 – 1980',subtitle:'A second laboratory. A different horizon.',theme:'Testing biology carefully',url:'https://science.nasa.gov/mission/viking-2/',imageUrl:'https://assets.science.nasa.gov/dynamicimage/assets/science/psd/solar/2023/07/PIA01522.jpg?w=1400',caption:'NASA/JPL · PIA01522: a historical Viking 2 surface image showing lander hardware and a Martian boulder field.',end:'Viking 2 landed September 3, 1976. The surface lander stopped transmitting in April 1980; its separate orbiter ended operations in July 1978.',stats:[['1976','Utopia Planitia landing'],['RTGs','Electrical power'],['1980','Lander mission ended']],parts:[['Surface cameras','The cameras documented Utopia Planitia, providing visual context for the lander’s measurements and sampled soil.'],['Sampler arm','The arm collected nearby soil for onboard chemical and biological experiments. Those tests did not establish a confirmed discovery of living organisms.'],['RTG generators','Two radioisotope thermoelectric generators supplied electricity by converting heat from radioactive decay; Viking 2 was not solar-powered.']],question:'What did Viking 2’s biology experiments establish?',choices:['A confirmed discovery of living organisms.','An answer that required no interpretation.','Results that were inconclusive about life.'],correct:2,why:'The experiments returned results that required careful interpretation and did not establish a confirmed discovery of Martian life.'},[
['A second laboratory reaches Mars','UTOPIA PLANITIA · SEPTEMBER 1976','Viking 2 arrived at a different part of Mars from its twin. Its lander touched down in Utopia Planitia on September 3, 1976, while a separate orbiter continued working above the planet. The cameras revealed a rocky landscape that scientists could compare with the Viking 1 site. This was a stationary laboratory. Instead of driving between faraway targets, the lander investigated the ground and atmosphere it could reach from one place, combining pictures, weather observations and experiments on nearby soil.'],
['A handful of ground enters a laboratory','CAMERAS, SAMPLER AND ELECTRICITY','The sampler arm collected material and delivered it to instruments on the lander. Cameras helped the team see the work and the surrounding surface. Two radioisotope thermoelectric generators supplied electrical power, using heat from radioactive decay rather than collecting sunlight with solar panels. These design choices supported a long working period on Mars. Each instrument had a different task. An image could show the setting of a sample, while laboratory tests investigated properties that could not be understood simply by looking at its color or shape.'],
['A difficult result is still a result','BIOLOGY AND CHEMISTRY','Viking 2’s soil experiments produced results similar to those of Viking 1: they were inconclusive about whether life existed, or had existed, on the Martian surface. Chemical reactions can sometimes resemble signs associated with living organisms. Scientists therefore had to compare different measurements and consider nonbiological explanations. The lesson is not that the mission failed to ask a useful question. It is that a careful experiment may narrow what can be claimed while leaving important questions open for later investigations.'],
['Two spacecraft have different endings','LANDER MISSION ENDS · APRIL 1980','The Viking 2 orbiter ended operations in July 1978, but its surface partner continued transmitting until April 1980. Their records describe different spacecraft and different parts of the mission. The abandoned artifact explored here is the lander at Utopia Planitia, not the orbiter. Its images and measurements had already reached Earth and could be studied after the hardware went quiet. The model represents the working lander design; it does not measure the equipment’s exact present condition after decades of exposure on Mars.']]);

item({id:'pathfinder',name:'Mars Pathfinder',world:'Mars',place:'Ares Vallis',lat:19.13,lon:-33.22,years:'1997',subtitle:'A bouncing arrival opens a new route.',theme:'Landing with airbags',url:'https://science.nasa.gov/mission/mars-pathfinder/',imageUrl:'https://science.nasa.gov/wp-content/uploads/2017/12/pia00621-pathfinder-and-sojourner-with-airbags-deflated.jpg?w=1400',caption:'NASA/JPL · PIA00621: Mars Pathfinder and Sojourner with deflated airbags, a historical mission image.',end:'Mars Pathfinder landed July 4, 1997, and returned its final data September 27, 1997. The lander and Sojourner are separate pieces of hardware left in Ares Vallis.',stats:[['1997','Mars landing'],['Airbags','Landing protection'],['Ares','Vallis site']],locationNote:'Approximate historical Ares Vallis landing region. Published coordinates vary with coordinate systems and mapping updates; this is not a surveyed parking point for Sojourner.',parts:[['Camera mast','The lander’s imaging system photographed the site and helped the team plan Sojourner’s route and scientific targets.'],['Opening petals','The protective lander petals opened after the airbag-cushioned landing, exposing equipment and letting the rover reach the ground.'],['Solar panels','Solar cells on the lander petals collected sunlight for electrical power during surface operations.']],question:'How were Pathfinder and Sojourner related?',choices:['They were the same machine with two names.','Pathfinder was the lander that delivered a separate rover, Sojourner.','Sojourner was the orbiter above Pathfinder.'],correct:1,why:'Pathfinder was the surface lander and communications station; Sojourner was the separate six-wheeled rover it delivered.'},[
['A landing with a surprising shape','ARES VALLIS · JULY 4, 1997','Mars Pathfinder tested a different way to reach the surface of Mars. Airbags surrounded its lander and the stowed rover during the final part of arrival, cushioning a landing that included bounces before the spacecraft came to rest. On July 4, 1997, Pathfinder reached Ares Vallis, a region selected for investigation of rocks and soil. The airbag system was part of getting there, not a way to travel during the science mission. Once the lander had settled, another carefully planned sequence could begin.'],
['A closed package opens a workplace','PETALS, CAMERA AND PANELS','Pathfinder’s petals opened to reveal its equipment and make a route for the rover. Its camera system observed the landscape, helping people on Earth choose targets and understand the surroundings. Solar cells on the petals collected sunlight for electrical power. A small six-wheeled rover, Sojourner, could then leave the lander and investigate nearby materials. It is useful to distinguish the two artifacts: Pathfinder was the stationary landing and communications base, while Sojourner supplied mobility and instruments that could approach selected rocks.'],
['A landing method supports real science','ROCKS, SOIL AND WEATHER','The mission did more than demonstrate its arrival system. Cameras, rover instruments and weather observations produced evidence about the site. Scientists could study rock and soil properties in their landscape context and investigate the environmental history recorded there. These observations supported questions about a warmer, wetter Martian past. They did not establish a discovery of living organisms. Engineering and science were connected: a successful landing and an operating communications station made it possible for a small mobile instrument carrier to investigate another planet.'],
['A base station becomes an archive','FINAL DATA · SEPTEMBER 27, 1997','Pathfinder’s final data transmission was September 27, 1997. The lander remained in Ares Vallis, near the rover it had delivered. Images of the working site preserve a particular period in the mission rather than the exact present appearance of the hardware. Its enduring story combines a landing experiment with surface observations: airbags helped a package reach the ground, petals opened a workspace, and a radio link brought measurements home. The historic record survived even though the machines were never designed to return to Earth.']]);

item({id:'sojourner',name:'Sojourner',world:'Mars',place:'Ares Vallis · Pathfinder site',lat:19.13,lon:-33.22,years:'1997',subtitle:'Six small wheels. A planet of questions.',theme:'A mobile rock investigator',url:'https://science.nasa.gov/mission/mars-pathfinder/',imageUrl:'https://assets.science.nasa.gov/dynamicimage/assets/science/psd/solar/2023/09/p/i/a/0/PIA01551-1.jpg?w=1200',caption:'NASA/JPL · PIA01551: the newly deployed Sojourner rover, photographed during the Mars Pathfinder mission in 1997.',end:'Sojourner was delivered July 4, 1997. Pathfinder’s final transmission was September 27, 1997, ending the documented joint surface mission. Sojourner remains a separate rover near its lander.',stats:[['6','Wheels'],['1997','Rover on Mars'],['APXS','Elemental analysis']],locationNote:'Approximate Pathfinder landing region. Sojourner is separate hardware at that site; its exact final parking position is not asserted by this marker.',parts:[['Rover cameras','The cameras supported navigation and observation of rocks and terrain near the lander.'],['APXS instrument','The rear-mounted alpha proton X-ray spectrometer investigated the elemental composition of rocks and soil when positioned close to a target.'],['Solar panel','The panel converted sunlight into electricity for the rover’s systems; the wheels did not use a gasoline engine.']],question:'Why did Sojourner drive close to selected rocks?',choices:['To position instruments for measurements of their composition.','To collect rocks for a return flight to Earth.','To prove that the rocks contained living organisms.'],correct:0,why:'The rover carried a close-up elemental analyzer, so mobility allowed its science tools to approach selected targets.'},[
['A rover rolls into the picture','PATHFINDER SITE · JULY 1997','The Mars Pathfinder mission carried two related explorers: a stationary lander and a small rover called Sojourner. After the July 4, 1997 landing, Sojourner could roll away from the lander and approach nearby rocks. Earth-based operators planned its investigations. Its six wheels made it more than a camera standing in one place. The rover could carry an instrument to a selected target, allowing researchers to connect a rock’s appearance with measurements made close to it. The lander remained its nearby base and communications connection.'],
['Move the instrument to the question','WHEELS, CAMERAS AND APXS','Sojourner’s cameras helped with navigation and surface observations. At the rear, its alpha proton X-ray spectrometer could investigate the elemental composition of rocks and soil. To use a close-up instrument well, the rover had to reach an appropriate position beside a target. Movement was therefore a scientific capability, not simply a way to make the mission look adventurous. The solar panel supplied electrical energy for the little rover’s systems. Its design joined mobility, sensing and communications in a compact machine built for another planet.'],
['A rock is more than its color','IMAGING AND ELEMENTAL ANALYSIS','Pictures show shape, texture and surroundings, but they cannot by themselves identify every chemical property of a rock. Sojourner added elemental measurements from its close-up instrument. The joint Pathfinder mission’s observations supported scientific investigations of Mars’s rocks, soil, weather and environmental past. This did not mean that one little rover could settle every question about the entire planet. Useful findings came from relating measurements to their targets and context. Evidence involving an ancient watery environment remained different from proof that living organisms had been found.'],
['The little rover stays with its story','A JOINT MISSION BECOMES HISTORY','Pathfinder sent its final data on September 27, 1997. The lander and Sojourner remained separate pieces of equipment in the same general site at Ares Vallis. A shared mission does not make them the same artifact: one provided the base, while the other moved instruments between targets. Historical images preserve their working period. The approximate globe marker identifies the region, not a live position or a precisely surveyed final parking place. Their records let people keep learning from a small machine’s first explorations on Martian ground.']]);

item({id:'ingenuity',name:'Ingenuity',world:'Mars',place:'Valinor Hills region · Jezero crater',lat:18.4,lon:77.6,years:'2021 – 2024',subtitle:'A flying experiment finds its final airfield.',theme:'Flight in a thin atmosphere',url:'https://science.nasa.gov/mission/mars-2020-perseverance/ingenuity-mars-helicopter/',imageUrl:'https://assets.science.nasa.gov/dynamicimage/assets/science/psd/mars/downloadable_items/4/5/45954_PIA24581.jpg?w=1200',caption:'NASA/JPL-Caltech/ASU/MSSS · PIA24581: Ingenuity on Mars during its working mission, photographed in 2021; not its final airfield.',end:'Ingenuity completed 72 flights. Its final flight was January 18, 2024; NASA announced the end of its flight mission January 25 after rotor damage. Flight retirement does not mean every electronic system immediately stopped.',stats:[['72','Flights'],['2024','Flight retirement'],['Solar','Electrical power']],locationNote:'Broad Jezero crater region locator only. The story identifies Valinor Hills as the final airfield; this marker is not a surveyed coordinate of the retired helicopter.',parts:[['Camera and body','Cameras documented flights and supported navigation. The small body carried the electronics and systems needed for the flight experiment.'],['Counter-rotating rotors','The two rotors spun in opposite directions to generate lift in Mars’s thin atmosphere. Rotor damage after the final flight made further flights impossible.'],['Solar panel','The panel charged batteries that supplied electricity for the helicopter’s powered systems and flights.']],question:'What did Ingenuity’s mission demonstrate?',choices:['That Mars has air as dense as Earth’s.','That a helicopter needs no electrical power.','That powered, controlled flight is possible in Mars’s thin atmosphere.'],correct:2,why:'Ingenuity demonstrated powered flight in the thin Martian atmosphere. It was a technology experiment, not a discovery of life.'},[
['A small aircraft carries a large question','JEZERO CRATER · 2021','Could a powered aircraft fly in Mars’s thin atmosphere? Ingenuity travelled with the Perseverance mission to test that possibility. It was a small helicopter designed as a technology demonstration, not a person-carrying aircraft. Its first flights would establish whether controlled flight could work in an environment very different from Earth’s. Demonstrating a capability is a meaningful kind of experiment: before using a new method for wider exploration, engineers need evidence that its hardware and control systems can operate on another world.'],
['Sunlight, stored energy and spinning blades','A DESIGN FOR MARTIAN FLIGHT','Ingenuity’s solar panel charged its batteries, which supplied electricity to the helicopter’s systems. Its two rotors turned in opposite directions and produced lift for flight. Cameras supported navigation and documented what the helicopter observed. These parts had to work together: energy was needed before the blades could spin, and control was needed to turn lift into a planned journey. The model explains that working design. It is an original illustration rather than a measured reconstruction of damage or a current-condition scan of the aircraft.'],
['A demonstration grows into a long experiment','SEVENTY-TWO FLIGHTS','Ingenuity exceeded its initial demonstration and completed seventy-two flights. Its observations and flight experience helped explore how an aerial scout could contribute to investigations of Martian terrain. The central result was engineering evidence that powered, controlled flight was possible in the thin atmosphere of Mars. That is different from carrying a full geological laboratory or proving the existence of living organisms. Each flight also depended on understanding the ground and conditions well enough for a tiny aircraft to take off, navigate and return to a surface landing.'],
['The final airfield','FLIGHT MISSION ENDS · JANUARY 2024','Ingenuity made its final flight on January 18, 2024. After rotor damage, NASA announced the end of its flight mission on January 25. The team nicknamed its final airfield Valinor Hills, within Jezero crater. Flight retirement means that the aircraft could no longer fly; it does not imply that every electronic system immediately stopped. The helicopter stayed on Mars while its images, flight records and engineering lessons remained available on Earth. This globe uses a broad Jezero region marker, not a surveyed point at the final airfield.']]);

item({id:'polarlander',name:'Mars Polar Lander',world:'Mars',place:'Intended south-polar landing region',lat:-76,lon:165,years:'Lost in 1999',subtitle:'The story with an unanswered landing.',theme:'Learning from a lost mission',url:'https://science.nasa.gov/mission/mars-polar-lander-deep-space-2/',imageUrl:'https://assets.science.nasa.gov/dynamicimage/assets/science/psd/solar/2023/07/1699_mpl_768.jpg?w=1100',caption:'NASA/JPL-Caltech · Artist’s concept of Mars Polar Lander deployed on Mars. This is a planned design illustration, not evidence of a successful landing.',end:'Mars Polar Lander was lost during arrival on December 3, 1999. Contact attempts ended January 17, 2000. Its exact resting location is unconfirmed; planned surface science was not achieved.',stats:[['1999','Lost during arrival'],['Planned','Polar investigation'],['Unknown','Resting position']],locationNote:'Uncertain location: intended target near 76° S, 195° W (165° E), not a confirmed resting location. The first-person exhibit shows a planned design, not a found intact wreck.',parts:[['Planned camera mast','The intended imaging system would have observed the surface. The mission did not return the planned surface photographs.'],['Planned robotic arm','The arm was intended to dig for water ice near the south polar cap. The planned sampling investigation was not successfully carried out.'],['Planned solar arrays','The deployed design included solar arrays to supply electrical power. The illustration shows intended hardware, not a confirmed intact lander on the surface.']],question:'What can we safely say about Mars Polar Lander?',choices:['It completed the planned polar soil experiments.','It was lost on arrival, and its exact resting location remains unconfirmed.','A photograph proves it still stands intact.'],correct:1,why:'The mission was lost during arrival. A design illustration and a target-region marker do not establish a successful landing or a confirmed wreck location.'},[
['A mission for the frozen south','PLANNED ARRIVAL · DECEMBER 1999','Mars Polar Lander was designed to investigate the frigid region near the edge of Mars’s south polar cap. A robotic arm would dig into the surface, and instruments would study material and the polar environment. Two small Deep Space 2 probes accompanied the mission as separate experimental hardware. The intended destination promised questions about ice and the history held in layered deposits. These were mission objectives, not results. Understanding this artifact begins with keeping the planned investigation separate from the events that actually occurred.'],
['A model shows an intention','THE PLANNED WORKING DESIGN','The illustration shows the lander’s intended deployed form: supporting legs, solar arrays, a camera mast and a robotic arm. On a successful surface mission, these parts would have connected imaging, sampling, energy and communication. But a design drawing is not a photograph proving that equipment arrived intact. In this experience you can inspect the planned hardware to learn what it was built to do. The verbs matter: the arm was intended to dig, and the camera was intended to observe. They did not return the planned surface science.'],
['An arrival without the expected reply','MARS ARRIVAL · DECEMBER 3, 1999','Mars Polar Lander and Deep Space 2 were lost on arrival on December 3, 1999. The expected surface communications did not establish a successful working lander. Engineers investigated how the mission might have failed, including a likely false touchdown signal that could have stopped the engines too early. That is an investigated explanation, not a filmed reconstruction of the final moments. A lost mission teaches a different kind of lesson: teams must distinguish evidence, a probable cause and the parts of an event that remain uncertain.'],
['Leave room for the unknown','CONTACT ATTEMPTS END · JANUARY 2000','NASA ended attempts to contact the lost lander on January 17, 2000. Its precise resting location has not been confirmed in the records used here. The globe marker therefore identifies an intended south-polar target region rather than an observed wreck. The first-person encounter is an illustrative design exhibit and cannot show what actually remained after arrival. Remembering the mission honestly includes both its scientific ambition and its missing results. An unanswered story can still teach us why careful engineering, communication and evidence are essential to exploration.']]);

const sourceId=id=>'collection'+id[0].toUpperCase()+id.slice(1);
export const collectionSources=Object.fromEntries(entries.map(a=>[sourceId(a.id),{title:a.name+' mission record',org:a.id==='falcon'?'NASA':'NASA Science',url:a.url,summary:a.end}]));
Object.assign(collectionSources,{
 collectionMplTarget:{title:'Mars Polar Lander target region',org:'NASA NSSDCA',url:'https://nssdc.gsfc.nasa.gov/planetary/mars/polar_lander/mpl_ds2_landsite.html',summary:'The intended target was near 76 degrees south and 195 degrees west. These target-area coordinates do not identify a confirmed wreck.'},
 collectionIngenuityAirfield:{title:'Ingenuity at its final airfield',org:'NASA/JPL-Caltech',url:'https://science.nasa.gov/resource/perseverance-spots-ingenuity-at-its-final-airfield/',summary:'A February 2024 rover mosaic shows Ingenuity at its final airfield, nicknamed Valinor Hills. The image is a dated observation, not a live view.'},
 collectionApollo15Details:{title:'Apollo 15 mission details',org:'NASA',url:'https://www.nasa.gov/missions/apollo/apollo-15-mission-details/',summary:'Apollo 15 used Falcon for surface exploration at Hadley-Apennine. Its ascent stage lifted the crew away August 2, 1971; the descent stage stayed at the site.'},
 collectionPathfinderLocation:{title:'Mars Pathfinder historical landing record',org:'NASA/JPL',url:'https://mars.nasa.gov/internal_resources/815/',summary:'A historical account places the airbag-cushioned landing in Ares Vallis near 19.13 degrees north, 33.22 degrees west. Mapping systems give slightly different coordinates.'},
 collectionSurveyorProgram:{title:'NASA Ranger and Surveyor programs',org:'NASA Science',url:'https://science.nasa.gov/mission/lunar-rangers-and-surveyors/',summary:'Five successful Surveyors performed robotic soft landings, photography and instrument operations before Apollo. Hardware and objectives varied among missions.'}
});
const extraRefs=a=>a.id.startsWith('surveyor')?['collectionSurveyorProgram']:a.id==='falcon'?['collectionApollo15Details']:a.id==='ingenuity'?['collectionIngenuityAirfield']:a.id==='polarlander'?['collectionMplTarget']:['pathfinder','sojourner'].includes(a.id)?['collectionPathfinderLocation']:[];
const refsFor=a=>[sourceId(a.id),...extraRefs(a)];
const file=a=>`collection-${a.id}.jpg`;
const firstSentence=text=>text.split('. ')[0]+'.';
const aliases={surveyor1:['Surveyor 1','Surveyor I'],surveyor5:['Surveyor 5','Surveyor V'],surveyor6:['Surveyor 6','Surveyor VI'],surveyor7:['Surveyor 7','Surveyor VII'],falcon:['Falcon','Falcon descent stage','Apollo 15 Lunar Module'],viking2:['Viking 2','Viking2','Viking 2 lander'],pathfinder:['Mars Pathfinder','Pathfinder','Carl Sagan Memorial Station'],sojourner:['Sojourner','Sojourner rover','Pathfinder rover'],ingenuity:['Ingenuity','Ingenuity Mars Helicopter','Mars Helicopter'],polarlander:['Mars Polar Lander','Polar Lander','MPL']};
export const collectionArtifacts=entries.map(a=>({
 id:a.id,code:a.name.toUpperCase()+' / '+a.years,name:a.name,aliases:aliases[a.id],mission:a.id==='falcon'?'Apollo 15':a.name,subtitle:a.subtitle,world:a.world,place:a.place,years:a.years,locationUncertain:a.id==='polarlander',
 status:a.id==='polarlander'?'Lost · resting site unconfirmed':a.id==='falcon'?'Descent stage left behind':a.id==='ingenuity'?'Flight mission retired':'Mission complete · hardware left behind',
 image:file(a),evidenceImage:file(a),imageCredit:a.caption,theme:a.theme,tag:a.id==='sojourner'?'ROVER':a.id==='ingenuity'?'HELICOPTER':a.id==='falcon'?'DESCENT STAGE':'ROBOTIC LANDER',
 model:null,modelType:a.id,narrationFormat:'mp3',
 modelNote:'Original ECHOES working-design illustration based on NASA records. Not a NASA-supplied mesh or a scan of current hardware.'+(a.id==='polarlander'?' This depicts the planned design; no intact surface lander or precise resting place is confirmed.':a.id==='falcon'?' Only the lower descent stage is shown, because the ascent stage departed.':''),
 lat:a.lat,lon:a.lon,coordinate:(a.id==='polarlander'?'Intended target only · ':'Approx. ')+`${Math.abs(a.lat)}° ${a.lat>=0?'N':'S'} · ${Math.abs(a.lon)}° ${a.lon>=0?'E':'W'}`,
 locationNote:a.locationNote||'Approximate historical mission-record location. This is a regional teaching marker, not a present-day surface survey.',
 intro:firstSentence(a.chapters[0][2]),stats:a.stats,refs:refsFor(a),
 chapters:[a.chapters[0],a.chapters[2],a.chapters[3]].map(([title,year,text])=>({title,year,text,ref:sourceId(a.id)})),
 hotspots:a.parts.map(([name,text],i)=>({name,text,ref:sourceId(a.id),position:[[0,.5,.2],[1,-.4,.2],[0,1,0]][i]})),
 question:a.question,choices:a.choices,correct:a.correct,why:a.why,evidence:sourceId(a.id),legacy:a.subtitle,legacyText:firstSentence(a.chapters[3][2]),endText:a.end,endRef:sourceId(a.id)
}));
const paragraphs=text=>{const i=text.indexOf('. ',Math.floor(text.length/2));return i<0?[text]:[text.slice(0,i+1),text.slice(i+2)];};
export const collectionLearningStories=Object.fromEntries(entries.map(a=>[a.id,{tagline:a.subtitle,chapters:a.chapters.map(([title,time,text])=>({title,time,paragraphs:paragraphs(text),image:file(a),caption:a.caption,refs:refsFor(a)}))}]));
export const collectionStories=Object.fromEntries(collectionArtifacts.map(a=>[a.id,a.chapters.map(c=>({title:c.title,line:a.subtitle,text:c.text,image:a.image,caption:a.imageCredit,ref:c.ref}))]));
export const collectionLearning=Object.fromEntries(collectionArtifacts.map(a=>[a.id,{chapterParts:[0,1,2],parts:a.hotspots.map((h,i)=>({prompt:`Can you find my ${h.name.toLowerCase()}?`,hint:`Choose part 0${i+1}: ${h.name}. Turn the illustration to see it from another side.`,simple:h.text,discovery:a.legacyText,ref:h.ref}))}]));
export const collectionAnswers=Object.fromEntries(collectionArtifacts.map(a=>[a.id,[
 {q:'What was your mission?',tags:'purpose mission sent why job',science:collectionLearningStories[a.id].chapters[0].paragraphs.join(' '),story:a.intro,refs:[a.refs[0]]},
 {q:'How did your equipment work?',tags:'instrument tool work power battery panel camera wheel rotor sampler arm design',science:a.hotspots.map(h=>h.text).join(' '),story:a.hotspots[0].text,refs:[a.refs[0]]},
 {q:'What did you help scientists learn?',tags:'learn discovery discover evidence science result geology chemistry life',science:a.why,story:a.why,refs:[a.evidence]},
 {q:'Where did your mission end?',tags:'end last stop contact shutdown finish where location remain left now',science:a.endText+' '+a.locationNote,story:a.endText,refs:a.refs}
]]));
export const collectionVoyages=Object.fromEntries(collectionArtifacts.map(a=>[a.id,{
 title:a.name+'.<br>'+a.subtitle,tag:a.theme,
 intro:`I am ${a.name}. ${a.subtitle} Explore my design and the NASA records that explain my mission. ${a.id==='polarlander'?'My planned surface investigation never happened; this is a design exhibit, not a discovered intact wreck.':'These words are an original storytelling voice, not historical speech.'}`,
 ending:a.endText,takeaway:a.why,
 scenes:[
  {title:collectionLearningStories[a.id].chapters[0].title,time:collectionLearningStories[a.id].chapters[0].time,line:`Look closely at this design. Find the ${a.hotspots[0].name.toLowerCase()} and discover its role in the mission.`,type:'part',target:0,action:`Find the ${a.hotspots[0].name.toLowerCase()}`,ref:a.hotspots[0].ref,success:a.hotspots[0].text},
  {title:collectionLearningStories[a.id].chapters[1].title,time:collectionLearningStories[a.id].chapters[1].time,line:`A different part has a different job. Find the ${a.hotspots[1].name.toLowerCase()} to continue the story.`,type:'part',target:1,action:`Find the ${a.hotspots[1].name.toLowerCase()}`,ref:a.hotspots[1].ref,success:a.hotspots[1].text},
  {title:collectionLearningStories[a.id].chapters[2].title,time:collectionLearningStories[a.id].chapters[2].time,line:`Follow NASA’s record: ${a.question}`,type:'choice',choices:a.choices,target:a.correct,focus:1,ref:a.evidence,hint:a.why,success:a.why},
  {title:collectionLearningStories[a.id].chapters[3].title,time:collectionLearningStories[a.id].chapters[3].time,line:a.id==='polarlander'?'Reveal this NASA artist’s concept. It shows the planned design, not a confirmed successful landing.':'Reveal this NASA archive image and connect the design with its recorded history.',type:'reveal',image:a.image,caption:a.imageCredit,action:'Reveal the NASA archive image',ref:a.refs[0],success:a.endText}
 ]
}]));
